'use strict';
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,page='home',filter='all',search='',selectedChat='',pollTimer=null,quiz=null,toastTimer;
const app=$('#app'),dialog=$('#dialog'),body=$('#dialog-body');
const teacher=()=>['admin','teacher'].includes(state?.user.role);
const isAdmin=()=>state?.user.role==='admin';
const roleName=()=>({admin:'Quản trị viên',teacher:'Giáo viên',parent:'Phụ huynh'})[state?.user.role]||'';
const find=(kind,id)=>state?.[kind]?.find(x=>x.id===id);
const title=(kind,id)=>find(kind,id)?.name||find(kind,id)?.title||'—';
const stamp=(v,long=false)=>v?new Date(v*1000).toLocaleString('vi-VN',long?{}:{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'';
const dueLabel=d=>d?d.split('-').reverse().join('/'):'Không giới hạn';
const typeLabel={quiz:'Trò chơi',text:'Bài văn bản',audio:'Âm thanh MP3',video:'Video MP4',html:'Game tải lên',link:'Game liên kết'};
const typeIcon={quiz:'🎮',text:'📄',audio:'🎵',video:'🎬',html:'🕹️',link:'🔗'};
const countUnread=()=>state?.notifications.filter(n=>!n.read_at).length||0;
function toast(msg,error=false){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',4500)}
async function api(path,data){const headers={'Content-Type':'application/json'};if(state?.csrf)headers['X-CSRF-Token']=state.csrf;const r=await fetch('/api/'+path,data===undefined?{}:{method:'POST',headers,body:JSON.stringify(data)});const v=await r.json();if(!r.ok){if(r.status===401){state=null;stopPolling();showLogin()}throw Error(v.error||'Không thể kết nối máy chủ.')}return v}
async function load(render=true){state=await api('bootstrap');if(render)renderApp();return state}
function stopPolling(){if(pollTimer)clearInterval(pollTimer);pollTimer=null}
function startPolling(){stopPolling();pollTimer=setInterval(async()=>{if(document.hidden||dialog.open||!state)return;try{const before=JSON.stringify(state.messages),unread=countUnread();await load(false);if(page==='messages'&&JSON.stringify(state.messages)!==before)renderPage();if(countUnread()!==unread)updateBell()}catch{}},12000)}
function updateBell(){let b=$('[data-action="notifications"]');if(b)b.innerHTML='🔔'+(countUnread()?`<em>${countUnread()}</em>`:'')}
function openDialog(title,html,wide=false){$('#dialog-title').textContent=title;body.innerHTML=html;if(!dialog.open)dialog.showModal();$('#dialog-body').scrollTop=0}
$('#close-dialog').addEventListener('click',()=>{dialog.close();quiz=null});dialog.addEventListener('click',e=>{if(e.target===dialog){dialog.close();quiz=null}});
function brand(){return '<div class="brand"><img src="assets/sun.svg" alt="Mặt trời vui vẻ"><div><div class="brand-name">Học nào <span>bé ơi!</span></div><div class="brand-tagline">Bé học vui · Cô dạy sáng tạo</div></div></div>'}
function showLogin(){app.innerHTML=`<main class="login-page"><div class="login-top">${brand()}<span class="chip">🌈 Cùng con lớn lên mỗi ngày</span></div><div class="login-layout"><section class="login-visual"><span class="eyebrow">Ngôi nhà nhỏ của những niềm vui</span><h1>Mỗi ngày khám phá,<br><span>mỗi ngày lớn khôn.</span></h1><p>Kết nối yêu thương giữa cô giáo và gia đình. Để từng bài học là một hành trình thật vui của bé.</p><div class="login-garden" role="img" aria-label="Hai bạn nhỏ trong khu vườn cầu vồng"></div><div class="login-pills"><span class="chip">🎮 Học qua trò chơi</span><span class="chip">💌 Gia đình đồng hành</span><span class="chip">🌱 Từng bước trưởng thành</span></div></section><section class="login-box"><h2>Xin chào, chào mừng bạn! 👋</h2><p>Cùng mở cánh cửa đến lớp học nhỏ của bé.</p><div class="role-pills"><span>👑 Admin</span><span>👩‍🏫 Giáo viên</span><span>👨‍👩‍👧 Gia đình</span></div><form id="login-form" class="stack"><label>Tên đăng nhập / Mã học sinh<input name="username" autocomplete="username" placeholder="Nhập tài khoản của bạn" required maxlength="80"></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" placeholder="Nhập mật khẩu" required maxlength="200"></label><div class="form-error" role="alert"></div><button class="btn" type="submit">Vào lớp học &nbsp; →</button></form><div class="login-separator">HOẶC KHÁM PHÁ ỨNG DỤNG</div><button class="btn outline" data-action="demo">🏆 Ban giám khảo trải nghiệm</button><p class="login-foot">Không cần tài khoản · Thử vai admin, giáo viên và phụ huynh<br>Dữ liệu mẫu riêng, không ảnh hưởng lớp học thật.</p></section></div><div class="login-footer">Học nào bé ơi! · Gia đình và nhà trường cùng đồng hành 💗</div></main>`;$('#login-form').addEventListener('submit',async e=>{e.preventDefault();await runForm(e.target,async()=>{await api('login',Object.fromEntries(new FormData(e.target)));page='home';await load();startPolling()})})}
const nav=[['home','🏠','Trang chủ'],['school','🏫','Trường / Năm học'],['grades','🧸','Khối học'],['classes','🏡','Lớp học'],['teachers','👩‍🏫','Giáo viên'],['students','👨‍👩‍👧','Học sinh / Phụ huynh'],['resources','🛠️','Game và bài tập'],['library','🎮','Kho game học mà chơi'],['assignments','📨','Giao bài tập'],['stories','📖','Nghe thơ truyện cùng bé'],['music','🎵','Giai điệu của bé'],['rankings','🏆','Kết quả thi đua'],['results','📊','Chi tiết bài làm'],['comments','💗','Nhận xét của cô'],['news','📣','Thông báo của cô'],['messages','💬','Tin nhắn'],['settings','⚙️','Cài đặt']];
function navItems(){return nav.filter(([p])=>teacher()||!['classes','parents','resources'].includes(p)).map(([p,e,n])=>[p,e,!teacher()&&p==='students'?'Con của tôi':!teacher()&&p==='assignments'?'Bài cô giao':n])}
function renderApp(){if(!state)return showLogin();app.innerHTML=`${state.user.demo?`<div class="demo-bar"><strong>🏆 KHU TRẢI NGHIỆM</strong><span>Dữ liệu mẫu riêng · Vai hiện tại: ${teacher()?'Giáo viên':'Phụ huynh'}</span><button class="btn small ${teacher()?'outline':'blue'}" data-action="switch" data-role="teacher">👩‍🏫 Giáo viên</button><button class="btn small ${teacher()?'blue':'outline'}" data-action="switch" data-role="parent">👨‍👩‍👧 Phụ huynh</button><select id="demo-parent" class="demo-select" aria-label="Chọn phụ huynh trải nghiệm"><option value="">Chọn gia đình khác…</option>${state.demo_parents.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>`:''}<header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Mở menu">☰</button>${brand()}<div class="top-slogan"><span>Mỗi ngày đến lớp<br>là một ngày vui! 🌈</span></div><div class="spacer"></div><button class="icon-btn bell" data-action="notifications" aria-label="Thông báo">🔔${countUnread()?`<em>${countUnread()}</em>`:''}</button><div class="profile"><span class="avatar">${teacher()?'👩‍🏫':'👨‍👩‍👧'}</span><div><small>${teacher()?'Giáo viên':'Phụ huynh'}</small><strong>${esc(state.user.name)}</strong></div></div><button class="icon-btn" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">↪</button></header><aside class="sidebar" id="sidebar"><div class="nav-label">LỚP HỌC CỦA CHÚNG MÌNH</div><nav>${navItems().map(([p,e,n])=>`<button class="nav-item ${page===p?'active':''}" data-page="${p}"><span class="emoji">${e}</span>${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-garden"></div><div class="sidebar-tip">💗 Mỗi lời động viên là một hạt mầm yêu thương.</div></div></aside><main class="main"><div id="page"></div><footer class="footer">${esc(state.school)} · Học nào bé ơi! ☀️</footer></main>`;renderPage();const dp=$('#demo-parent');if(dp)dp.onchange=async e=>{if(!e.target.value)return;try{await api('demo/switch',{role:'parent',user_id:e.target.value});page='home';selectedChat='';await load()}catch(e){toast(e.message,true)}}}
function navigate(p){page=p;filter='all';search='';renderApp();window.scrollTo({top:0,behavior:'smooth'})}
function pageHead(name,subtitle,action=''){return `<div class="page-head"><div><h1 class="page-title">${name}</h1><p>${subtitle}</p></div><div class="flex">${action}<button class="icon-btn" data-action="refresh" title="Làm mới" aria-label="Làm mới">↻</button></div></div>`}
function empty(icon,msg,sub=''){return `<div class="empty"><span class="empty-icon">${icon}</span><strong>${msg}</strong>${sub?`<p class="tiny">${sub}</p>`:''}</div>`}
function btn(label,action,id='',cls=''){return `<button class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`}
function resourceCard(r,i=0){let style=r.type==='audio'?'story':r.type==='video'?'fish':i%3===0?'bee':i%3===1?'fish':'story';let art=r.type==='audio'?'🌙 🎵 🧸':r.type==='video'?'🎬 🌈':r.type==='text'?'📚 ✏️':i%3===0?'🐝 🌼':i%3===1?'🐠 ❸':'🧩 🌈';return `<article class="card"><div class="card-top ${style}"><span class="badge">${typeIcon[r.type]} ${typeLabel[r.type]}</span><span class="card-art" aria-hidden="true">${art}</span>${btn(r.type==='quiz'?'▶ Chơi thử':'▶ Xem bài','preview',r.id,'play-overlay')}</div><div class="card-body"><h3>${esc(r.title)}</h3><span class="badge ${r.type==='audio'?'pink':''}">${r.type==='quiz'?r.questions.length+' câu hỏi':typeLabel[r.type]}</span><p>${esc(r.description||'Cùng bé khám phá những điều thú vị mỗi ngày.')}</p>${teacher()?`<div class="card-actions">${btn('📨 Giao bài','assign',r.id,'small blue')}${btn('Sửa','resource-edit',r.id,'small ghost')}${btn('Xóa','delete-resource',r.id,'small danger')}</div>`:''}</div></article>`}
function renderPage(){if(!state)return;const el=$('#page');if(!el)return;$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));const t=teacher();
if(page==='home'){const submitted=t?state.attempts.length:state.attempts.filter(a=>a.review).length;el.innerHTML=`<section class="hero"><div class="hero-copy"><h1>Học nào <span>bé ơi!</span></h1><p>Khám phá · Chơi mà học · Lớn lên mỗi ngày</p><div class="flex">${t?btn('🎮 Tạo game / bài tập','resource-new')+btn('📂 Quản lý lớp học','go-classes','','blue')+btn('📨 Giao bài cho lớp','assign','','orange'):btn('🎮 Khám phá bài cô giao','go-assignments')+btn('💬 Nhắn cho cô','go-messages','','blue')}</div></div></section><section class="stats">${[[t?'🏫':'👧',t?state.classes.length:state.students.length,t?'Lớp học':'Con của tôi'],['🎮',t?state.resources.length:state.assignments.length,t?'Game & bài tập':'Bài cô đã giao'],['🏆',t?submitted:state.attempts.length,t?'Lượt nộp bài':'Lượt bé hoàn thành'],['💗',t?state.attempts.filter(a=>a.review).length:submitted,'Nhận xét của cô']].map(([i,n,l])=>`<div class="stat"><span class="stat-icon">${i}</span><div><span class="stat-label">${l}</span><strong>${n}</strong><small>Cùng bé mỗi ngày</small></div></div>`).join('')}</section><section class="panel"><div class="section-head"><div><h2>🎮 ${t?'Game và bài tập':'Bài học dành cho bé'}</h2><p>Những khám phá nhỏ, niềm vui thật to</p></div>${btn('Xem tất cả','go-'+(t?'resources':'assignments'),'','small outline')}</div><div class="grid">${(t?state.resources:state.assignments.map(a=>find('resources',a.resource_id))).filter(Boolean).slice(0,3).map(resourceCard).join('')||empty('🌻','Lớp học đang chờ những bài học đầu tiên',t?'Bấm “Tạo game / bài tập” để bắt đầu.':'Cô sẽ gửi bài tại đây.')}</div></section><div class="two-col"><section class="panel"><div class="section-head"><h2>📣 Thông báo mới</h2>${btn('Xem thêm','go-news','','small ghost')}</div>${state.news.slice(0,3).map(n=>`<div class="activity"><span class="activity-icon">📮</span><div><strong>${esc(n.title)}</strong><p>${esc(n.body.slice(0,100))}${n.body.length>100?'…':''}</p><small>${stamp(n.created)}</small></div></div>`).join('')||empty('📮','Chưa có thông báo mới')}</section><div class="quote"><span class="big">🌱</span><h3>Mỗi em bé là một<br>bông hoa riêng biệt.</h3><p>Hãy để con tự khám phá, tự lựa chọn và lớn lên trong những lời động viên dịu dàng.</p><span class="badge pink">Gia đình & nhà trường đồng hành</span></div></div>`;return}
if(page==='classes'){el.innerHTML=pageHead('🏫 Lớp học','Quản lý lớp, độ tuổi và năm học của các bé.',btn('＋ Thêm lớp','class-new'))+`<div class="grid">${state.classes.map(c=>`<article class="panel"><div class="flex between"><span class="avatar">🏫</span><span class="badge">${esc(c.age)}</span></div><h3>${esc(c.name)}</h3><p class="muted tiny">Năm học ${esc(c.year)}</p><p><strong>${state.students.filter(s=>s.class_id===c.id).length}</strong> học sinh · <strong>${state.assignments.filter(a=>a.class_id===c.id).length}</strong> bài đã giao</p><div class="flex">${btn('Xem học sinh','class-students',c.id,'small blue')}${btn('Sửa','class-edit',c.id,'small ghost')}${btn('Xóa','delete-class',c.id,'small danger')}</div></article>`).join('')||empty('🏫','Chưa có lớp học','Bấm Thêm lớp để tạo lớp đầu tiên.')}</div>`;return}
if(page==='students'){el.innerHTML=pageHead(t?'👧 Học sinh':'👧 Con của tôi',t?'Mỗi học sinh có mã riêng và được liên kết với tài khoản phụ huynh.':'Thông tin và bài học của những người con được liên kết với tài khoản.',t?btn('＋ Thêm học sinh','student-new'):'')+`<div class="filterbar"><select id="student-class-filter" aria-label="Lọc theo lớp"><option value="all">Tất cả lớp học</option>${state.classes.map(c=>`<option value="${c.id}" ${filter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><input id="student-search" class="search" placeholder="🔎 Tìm tên, mã học sinh…" aria-label="Tìm học sinh" value="${esc(search)}"></div><div class="panel table-wrap" id="students-list"></div>`;renderStudents();$('#student-class-filter').onchange=e=>{filter=e.target.value;renderStudents()};$('#student-search').oninput=e=>{search=e.target.value;renderStudents()};return}
if(page==='parents'){el.innerHTML=pageHead('👨‍👩‍👧 Phụ huynh','Cấp tài khoản rồi liên kết khi thêm hoặc sửa hồ sơ học sinh.',btn('＋ Cấp tài khoản','parent-new'))+`<div class="note warm">🔐 Mật khẩu cần ít nhất 10 ký tự. Giáo viên chỉ tạo/đặt lại mật khẩu, không xem được mật khẩu đã lưu. Hãy gửi thông tin đăng nhập riêng cho từng gia đình.</div><div class="panel table-wrap"><table><thead><tr><th>Phụ huynh</th><th>Tên đăng nhập</th><th>Con được liên kết</th><th>Thao tác</th></tr></thead><tbody>${state.parents.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td><code>${esc(p.username)}</code></td><td>${state.students.filter(s=>s.parent_id===p.id).map(s=>esc(s.name)).join(', ')||'<span class="muted">Chưa liên kết</span>'}</td><td><div class="flex">${btn('Nhắn tin','chat',p.id,'small blue')}${btn('Sửa tên','parent-edit',p.id,'small ghost')}${btn('Đặt lại mật khẩu','parent-reset',p.id,'small outline')}</div></td></tr>`).join('')}</tbody></table>${!state.parents.length?empty('💌','Chưa có tài khoản phụ huynh'):''}</div>`;return}
if(page==='resources'){el.innerHTML=pageHead('🎮 Game và bài tập','Tạo trò chơi nhiều câu hỏi, bài văn bản, âm thanh và video.',btn('＋ Tạo mới','resource-new'))+`<section class="panel"><div class="filterbar"><div class="tabs">${[['all','Tất cả'],['quiz','🎮 Trò chơi'],['text','📄 Văn bản'],['audio','🎵 MP3'],['video','🎬 MP4']].map(([id,n])=>`<button class="tab ${filter===id?'active':''}" data-action="filter-resource" data-id="${id}">${n}</button>`).join('')}</div><input id="resource-search" class="search" placeholder="🔎 Tìm game, bài tập…" aria-label="Tìm học liệu" value="${esc(search)}"></div><div id="resource-list" class="grid"></div></section>`;renderResources();$('#resource-search').oninput=e=>{search=e.target.value;renderResources()};return}
if(page==='assignments'){el.innerHTML=pageHead(t?'📨 Giao bài cho lớp':'📚 Bài cô giao',t?'Giao cho cả lớp hoặc riêng từng bé. Phụ huynh mở và cho con làm trực tiếp.':'Chọn bài, cùng con khám phá và gửi kết quả cho cô.',t?btn('＋ Giao bài mới','assign'):'')+`<div class="stack">${state.assignments.map(a=>{let r=find('resources',a.resource_id);if(!r)return '';let attempts=state.attempts.filter(x=>x.assignment_id===a.id);return `<article class="panel"><div class="flex between"><div><span class="badge">${typeIcon[r.type]} ${typeLabel[r.type]}</span><h3>${esc(r.title)}</h3><p class="muted tiny">🏫 ${esc(title('classes',a.class_id))}${a.student_id?' · 👧 '+esc(title('students',a.student_id)):' · Cả lớp'}${a.origin==='practice'?' · 🎙️ Tự luyện':''} · Hạn: ${esc(dueLabel(a.due))}</p></div><span class="avatar">${typeIcon[r.type]}</span></div>${a.instructions?`<p class="pre tiny">${esc(a.instructions)}</p>`:''}<div class="flex between"><span class="chip">${attempts.length} lượt nộp ${!t&&attempts.length?'· Bé đã tham gia 🌟':''}</span><div class="flex">${btn(t?'Xem bài':'Mở bài cho con',t?'preview-assignment':'open-assignment',a.id,'blue')}${t?btn('Thu hồi','delete-assignment',a.id,'small danger'):''}</div></div></article>`}).join('')||empty('📚','Chưa có bài được giao',t?'Tạo học liệu rồi giao cho lớp nhé.':'Bài cô giao sẽ xuất hiện tại đây.')}</div>`;return}
if(page==='results'){el.innerHTML=pageHead('🏆 Kết quả & nhận xét',t?'Theo dõi bài làm và gửi lời động viên đến từng bé.':'Xem hành trình học tập và những lời động viên của cô.',t?btn('↓ Xuất kết quả CSV','export-results','','outline'):'')+`<div class="filterbar"><select id="results-student" aria-label="Lọc kết quả theo học sinh"><option value="all">Tất cả học sinh</option>${state.students.map(s=>`<option value="${s.id}" ${filter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><span class="chip">${state.attempts.length} lượt hoàn thành</span></div><div id="result-list"></div>`;renderResults();$('#results-student').onchange=e=>{filter=e.target.value;renderResults()};return}
if(page==='news'){el.innerHTML=pageHead('📣 Thông báo của cô','Những tin mới giúp gia đình và nhà trường luôn đồng hành.',t?btn('＋ Đăng thông báo','news-new'):'')+state.news.map(n=>`<article class="news-card"><div class="flex between"><span class="badge ${n.class_id?'':'pink'}">${n.class_id?'🏫 '+esc(title('classes',n.class_id)):'🌈 Toàn trường'}</span><span class="news-date">${stamp(n.created)}</span></div><h3>${esc(n.title)}</h3><div class="pre">${esc(n.body)}</div>${t?`<div class="flex card-actions">${btn('Chỉnh sửa','news-edit',n.id,'small ghost')}${btn('Xóa','delete-news',n.id,'small danger')}</div>`:''}</article>`).join('')+(state.news.length?'':empty('📣','Chưa có thông báo'));return}
if(page==='messages'){renderMessages(el);return}
if(page==='settings'){el.innerHTML=pageHead('⚙️ Cài đặt','Thông tin tài khoản và ngôi trường của bé.')+`<div class="two-col"><section class="panel"><h3>👤 Tài khoản của bạn</h3><p><strong>${esc(state.user.name)}</strong><br><code>${esc(state.user.username)}</code></p><p class="muted tiny">Vai trò: ${t?'Giáo viên':'Phụ huynh'}</p>${btn('Đổi mật khẩu','password','','outline')}</section><section class="panel"><h3>🏫 Thông tin trường</h3><p>${esc(state.school)}</p>${t?btn('Sửa tên trường','school','','outline'):''}<p class="muted tiny">Phiên đăng nhập tối đa 12 giờ. Bấm Làm mới nếu dữ liệu chưa cập nhật.</p></section></div><section class="panel"><h3>💡 Hướng dẫn nhanh</h3><p class="tiny">${t?'1. Thêm lớp → 2. Cấp tài khoản phụ huynh → 3. Thêm học sinh và liên kết → 4. Tạo học liệu → 5. Giao bài → 6. Xem kết quả và nhận xét.':'1. Xem thông báo → 2. Mở bài cô giao → 3. Chọn con đang học → 4. Cùng con làm bài → 5. Xem nhận xét và nhắn tin với cô.'}</p><div class="note">Bản này có chức năng học tập, chưa tích hợp API AI. Các bài mẫu do người lớn kiểm duyệt. Tin nhắn và thông báo chỉ gửi trong ứng dụng.</div></section>`;return}}
function renderResources(){const items=state.resources.filter(r=>(filter==='all'||r.type===filter)&&r.title.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));$('#resource-list').innerHTML=items.map(resourceCard).join('')||empty('🎮','Chưa có học liệu phù hợp');$$('.tab').forEach(t=>t.classList.toggle('active',t.dataset.id===filter))}
function renderStudents(){let students=state.students.filter(s=>(filter==='all'||s.class_id===filter)&&(s.name+' '+s.code).toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));$('#students-list').innerHTML=students.length?`<table><thead><tr><th>Học sinh</th><th>Mã học sinh</th><th>Lớp</th><th>${teacher()?'Phụ huynh':'Ngày sinh'}</th><th>Thao tác</th></tr></thead><tbody>${students.map(s=>`<tr><td><div class="student-cell"><span class="avatar">${['👧','👦'][state.students.indexOf(s)%2]}</span><div><strong>${esc(s.name)}</strong><div class="muted tiny">${esc(s.note.slice(0,60))}</div></div></div></td><td><code>${esc(s.code)}</code></td><td>${esc(title('classes',s.class_id))}</td><td>${esc(teacher()?title('parents',s.parent_id):dueLabel(s.birthday))}</td><td><div class="flex">${teacher()?btn('Sửa','student-edit',s.id,'small ghost')+btn('Xóa','delete-student',s.id,'small danger'):btn('Xem bài','go-assignments','','small blue')}</div></td></tr>`).join('')}</tbody></table>`:empty('👧','Chưa có học sinh phù hợp',teacher()?'Tạo tài khoản phụ huynh trước rồi thêm học sinh.':'Liên hệ giáo viên để liên kết hồ sơ con.')}
function fileLink(id){const f=find('files',id);return f?`<a class="file-tag" href="/api/files/${encodeURIComponent(id)}?download=1">📎 ${esc(f.name)} ↓</a>`:''}
function renderResults(){const attempts=state.attempts.filter(a=>filter==='all'||a.student_id===filter);$('#result-list').innerHTML=attempts.map(a=>{const assignment=find('assignments',a.assignment_id),resource=find('resources',assignment?.resource_id);return `<article class="result-card"><div class="flex between"><div><span class="badge">👧 ${esc(title('students',a.student_id))}</span><h3>${esc(resource?.title||'Bài học')}</h3><span class="muted tiny">${stamp(a.created,true)}</span></div><span class="score">${a.total?a.score+'/'+a.total:'✓'}</span></div>${a.response?`<p class="pre">${esc(a.response)}</p>`:''}${fileLink(a.file_id)}${a.total?`<p class="tiny muted">${a.total} câu hỏi · Kết quả chấm tự động, cô theo dõi và động viên bé.</p>`:''}${a.review?`<div class="review-box"><strong>💗 Nhận xét của cô ${a.stars?`<span class="stars">${'★'.repeat(a.stars)}</span>`:''}</strong><p class="pre">${esc(a.review)}</p><small>${stamp(a.reviewed)}</small></div>`:'<p class="muted tiny">🌷 Cô sẽ sớm gửi nhận xét cho bé.</p>'}${teacher()?`<div class="flex card-actions">${btn(a.review?'Sửa nhận xét':'💗 Viết nhận xét','review',a.id,'small')}${btn('Xem bài làm','attempt-detail',a.id,'small outline')}</div>`:btn('Xem bài làm','attempt-detail',a.id,'small outline')}</article>`}).join('')||empty('🌟','Chưa có bài làm','Kết quả sẽ xuất hiện khi phụ huynh gửi bài của con.')}
function renderMessages(el){const contacts=teacher()?state.parents:[{id:state.user.id,name:'Cô giáo của bé',username:'Trao đổi cùng gia đình'}];if(!contacts.some(c=>c.id===selectedChat))selectedChat=contacts[0]?.id||'';let contact=contacts.find(p=>p.id===selectedChat);const messages=state.messages.filter(m=>m.parent_id===selectedChat);el.innerHTML=pageHead('💬 Tin nhắn',teacher()?'Trao đổi riêng, đồng hành cùng từng gia đình.':'Gửi lời nhắn và nhận phản hồi từ cô giáo.')+`<section class="chat-layout"><div class="chat-contacts">${contacts.map(p=>{const n=state.messages.filter(m=>m.parent_id===p.id&&m.sender_id!==state.user.id&&!m.read_at).length;return `<button class="contact ${selectedChat===p.id?'active':''}" data-action="chat" data-id="${p.id}"><span class="avatar">${teacher()?'👨‍👩‍👧':'👩‍🏫'}</span><span><strong>${esc(p.name)}</strong><small>${teacher()?state.students.filter(s=>s.parent_id===p.id).map(s=>esc(s.name)).join(', ')||'Chưa liên kết con':esc(p.username)}</small></span>${n?'<span class="dot"></span>':''}</button>`}).join('')||empty('💬','Chưa có phụ huynh')}</div><div class="chat-pane"><div class="chat-header">${esc(contact?.name||'Chọn một cuộc trò chuyện')} <span class="badge green">Tin nhắn trong ứng dụng</span></div><div class="chat-messages" id="chat-scroll">${messages.map(m=>`<div class="bubble ${m.sender_id===state.user.id?'mine':''}"><div class="pre">${esc(m.body)}</div><small>${esc(m.sender_name)} · ${stamp(m.created)}${m.sender_id===state.user.id&&m.read_at?' · Đã xem':''}</small></div>`).join('')||empty('💌','Bắt đầu bằng một lời chào nhé!')}</div>${contact?`<form id="message-form" class="chat-compose"><label class="sr-only" for="message-text">Nội dung tin nhắn</label><textarea id="message-text" name="body" maxlength="5000" placeholder="Nhập lời nhắn…" required></textarea><button class="btn blue" type="submit">Gửi ➤</button></form>`:''}</div></section>`;let scroll=$('#chat-scroll');scroll.scrollTop=scroll.scrollHeight;if(contact){api('messages/read',{parent_id:selectedChat}).catch(()=>{});$('#message-form').onsubmit=async e=>{e.preventDefault();const f=e.target;try{const b=$('button',f);b.disabled=true;await api('messages',{parent_id:selectedChat,body:new FormData(f).get('body')});await load(false);renderPage()}catch(err){toast(err.message,true);$('button',f).disabled=false}}}}
function field(key,label,value='',type='text',hint='',required=true){return `<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="4" autocomplete="new-password"':''} ${type==='text'?'maxlength="180"':''}>${hint?`<span class="hint">${hint}</span>`:''}</label>`}
function select(key,label,items,value='',placeholder='— Chọn —',required=true){return `<label>${label}<select name="${key}" ${required?'required':''}>${placeholder!==null?`<option value="">${placeholder}</option>`:''}${items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name||x.title)}</option>`).join('')}</select></label>`}
function area(key,label,value='',required=false,max=10000){return `<label>${label}<textarea name="${key}" ${required?'required':''} maxlength="${max}">${esc(value)}</textarea></label>`}
function modalForm(title,html,save,label='Lưu thông tin'){openDialog(title,`<form id="editor" class="stack">${html}<div class="form-error" role="alert"></div><div class="form-actions"><button class="btn ghost" type="button" data-action="close">Hủy</button><button class="btn" type="submit">${label}</button></div></form>`);const form=$('#editor');form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{await save(Object.fromEntries(new FormData(form)),form);dialog.close();await load();toast('Đã lưu thành công 🌷')})};return form}
async function runForm(form,fn){const button=$('button[type="submit"]',form);const err=$('.form-error',form);if(err){err.textContent='';err.classList.remove('show')}if(button)button.disabled=true;try{await fn()}catch(e){if(err){err.textContent=e.message;err.classList.add('show')}else toast(e.message,true)}finally{if(button)button.disabled=false}}
function classEditor(id){const c=find('classes',id)||{};modalForm(id?'Sửa thông tin lớp':'🏫 Thêm lớp học',`<div class="form-grid">${field('name','Tên lớp',c.name||'')}${select('age','Độ tuổi',['18–24 tháng','24–36 tháng','3–4 tuổi','4–5 tuổi','5–6 tuổi'].map(x=>({id:x,name:x})),c.age||'5–6 tuổi',null)}${field('year','Năm học',c.year||'2026–2027')}</div>`,d=>api('classes',{...d,id}))}
function studentEditor(id){if(!state.classes.length)return toast('Cô hãy tạo lớp học trước nhé.',true);if(!state.parents.length)return toast('Cô hãy cấp tài khoản phụ huynh trước nhé.',true);const s=find('students',id)||{};modalForm(id?'Sửa hồ sơ học sinh':'👧 Thêm học sinh',`<div class="form-grid">${field('name','Họ và tên học sinh',s.name||'')}${field('code','Mã học sinh',s.code||'','text','Để trống để tự sinh mã. Mã không phải mật khẩu.',false)}${select('class_id','Lớp học',state.classes,s.class_id||'')}${select('parent_id','Tài khoản phụ huynh liên kết',state.parents,s.parent_id||'')}${field('birthday','Ngày sinh',s.birthday||'','date','',false)}<div class="full">${area('note','Ghi chú của lớp',s.note||'',false,1000)}</div></div>`,d=>api('students',{...d,id}))}
function parentEditor(id){const p=find('parents',id)||{};modalForm(id?'Sửa tên phụ huynh':'👨‍👩‍👧 Cấp tài khoản phụ huynh',field('name','Tên phụ huynh',p.name||'')+(id?'':field('username','Tên đăng nhập','','text','Ví dụ: mebean. Dùng chữ thường không dấu, số, dấu . _ -')+field('password','Mật khẩu tạm thời','','password','Ít nhất 10 ký tự. Phụ huynh có thể đổi trong Cài đặt.'))+`<div class="note">Sau khi cấp tài khoản, vào Học sinh để liên kết với con. ${state.user.demo?'Đây là tài khoản mẫu; dùng nút đổi vai để thử.':''}</div>`,d=>api('parents',{...d,id}),id?'Lưu thay đổi':'Cấp tài khoản')}
function parentReset(id){modalForm('🔐 Đặt lại mật khẩu phụ huynh',`<p class="muted tiny">${esc(title('parents',id))} sẽ đăng xuất khỏi các phiên đang mở.</p>`+field('password','Mật khẩu mới','','password'),d=>api('parents/reset',{...d,id}),'Đặt lại mật khẩu')}
let resourceDraft=null;
function resourceEditor(id){const r=find('resources',id);if(r&&state.assignments.some(a=>a.resource_id===id))return toast('Bài đã giao được giữ nguyên để bảo toàn lịch sử. Cô hãy tạo học liệu mới.',true);resourceDraft=r?JSON.parse(JSON.stringify(r)):{title:'',description:'',type:'quiz',body:'',file_id:null,questions:[{question:'',options:['','',''],answer:0}]};openDialog(r?'Sửa game / bài tập':'🎮 Tạo game / bài tập',`<form id="resource-form" class="stack">${field('title','Tên game / bài tập',resourceDraft.title)}${area('description','Lời giới thiệu ngắn',resourceDraft.description,false,3000)}${select('type','Loại học liệu',Object.entries(typeLabel).map(([id,name])=>({id,name})),resourceDraft.type,null)}<div id="resource-fields"></div><div class="form-error" role="alert"></div><div class="form-actions"><button class="btn ghost" type="button" data-action="close">Hủy</button><button class="btn" type="submit">Lưu học liệu</button></div></form>`);drawResourceFields();const form=$('#resource-form');$('[name=type]',form).onchange=e=>{captureResourceFields();resourceDraft.type=e.target.value;resourceDraft.file_id=null;drawResourceFields()};form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{captureResourceFields();const d=Object.fromEntries(new FormData(form));let fid=resourceDraft.file_id;const file=$('[name=attachment]',form)?.files[0];if(file)fid=(await upload(file)).id;await api('resources',{id,...d,type:resourceDraft.type,questions:resourceDraft.type==='quiz'?resourceDraft.questions:[],body:resourceDraft.body,file_id:fid});dialog.close();await load();toast('Đã lưu học liệu. Cô có thể xem thử hoặc giao bài ngay!')})}}
function captureResourceFields(){const box=$('#resource-fields');if(!box)return;if(resourceDraft.type==='quiz'){const cards=$$('.question-editor',box);resourceDraft.questions=cards.map(card=>({question:$('[data-q=question]',card).value,options:$$('[data-q=option]',card).map(x=>x.value),answer:Number($('[data-q=answer]',card).value)}))}else if(resourceDraft.type==='text'){resourceDraft.body=$('[name=body]',box)?.value||''}}
function drawResourceFields(){const box=$('#resource-fields');if(resourceDraft.type==='quiz'){box.innerHTML=`<div class="note">Mỗi câu có 3 lựa chọn. Bé chạm vào đáp án trên điện thoại hoặc nhấp chuột trên máy tính. Tối đa 30 câu.</div><div id="questions">${resourceDraft.questions.map((q,i)=>`<div class="question-editor"><div class="flex between question-num"><span>CÂU HỎI ${i+1}</span>${resourceDraft.questions.length>1?`<button class="btn small danger" type="button" data-action="question-remove" data-id="${i}">Xóa câu</button>`:''}</div><label>Nội dung câu hỏi<input data-q="question" value="${esc(q.question)}" maxlength="1000" placeholder="Ví dụ: Bông hoa nào có chữ a?" required></label><div class="options-grid">${q.options.map((o,j)=>`<label>Lựa chọn ${j+1}<input data-q="option" value="${esc(o)}" maxlength="300" required></label>`).join('')}</div><label>Đáp án đúng<select data-q="answer">${q.options.map((o,j)=>`<option value="${j}" ${q.answer===j?'selected':''}>Lựa chọn ${j+1}</option>`).join('')}</select></label></div>`).join('')}</div><button class="btn outline small" type="button" data-action="question-add">＋ Thêm câu hỏi</button>`}else{const ext=resourceDraft.type==='audio'?'.mp3':resourceDraft.type==='video'?'.mp4':'.txt';box.innerHTML=`${resourceDraft.type==='text'?area('body','Nội dung bài học',resourceDraft.body,false,30000):''}<div class="upload-box">${typeIcon[resourceDraft.type]} ${resourceDraft.type==='text'?'Nhập văn bản ở trên hoặc tải tệp TXT (UTF-8).':'Chọn tệp '+ext.toUpperCase()+' từ máy tính.'}<br><small>Mỗi tệp tối đa 25 MB. MP4 nên dùng mã hóa H.264/AAC.</small><input type="file" name="attachment" accept="${ext}" aria-label="Tải học liệu ${ext}">${resourceDraft.file_id?`<p>📎 Đã có tệp: ${esc(find('files',resourceDraft.file_id)?.name||'Tệp học liệu')}</p>`:''}</div>`}}
async function upload(file){if(file.size>25*1024*1024)throw Error('Tệp quá lớn. Mỗi tệp tối đa 25 MB.');toast('Đang tải tệp…');const data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Không đọc được tệp.'));reader.readAsDataURL(file)});return api('files',{name:file.name,data})}
function assignEditor(resourceId){if(!state.classes.length||!state.resources.length)return toast('Cô cần có lớp học và học liệu trước khi giao bài.',true);const f=modalForm('📨 Giao bài cho các bé',select('resource_id','Chọn game / bài tập',state.resources,resourceId||'')+`<div class="form-grid">${select('class_id','Giao cho lớp',state.classes,'')}${select('student_id','Giao riêng cho bé (không bắt buộc)',[],'','Cả lớp',false)}</div>`+field('due','Hạn hoàn thành','','date','Phụ huynh vẫn có thể nộp sau hạn; cô theo dõi theo ngày gửi.',false)+area('instructions','Lời dặn dành cho phụ huynh','Bố mẹ đồng hành, để con tự lựa chọn và khám phá nhé!',false,3000),d=>api('assignments',d),'Giao bài & gửi thông báo');$('[name=class_id]',f).onchange=e=>{const options=state.students.filter(s=>s.class_id===e.target.value);$('[name=student_id]',f).innerHTML='<option value="">Cả lớp</option>'+options.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.code)}</option>`).join('')}}
function newsEditor(id){const n=find('news',id)||{};modalForm(id?'Sửa thông báo':'📣 Đăng thông báo',field('title','Tiêu đề',n.title||'')+select('class_id','Phạm vi nhận',state.classes,n.class_id||'','Toàn trường',false)+area('body','Nội dung thông báo',n.body||'',true,10000),d=>api('news',{...d,id}),'Đăng thông báo')}
function reviewEditor(id){const a=find('attempts',id);modalForm('💗 Lời nhận xét dành cho '+title('students',a.student_id),area('review','Nhận xét của cô',a.review||'',true,5000)+select('stars','Ngôi sao động viên',[{id:'0',name:'Không gắn sao'},...Array.from({length:5},(_,i)=>({id:String(i+1),name:'★'.repeat(i+1)}))],String(a.stars),null),d=>api('reviews',{...d,id,stars:Number(d.stars)}),'Lưu & thông báo phụ huynh')}
function attemptDetail(id){const a=find('attempts',id),assignment=find('assignments',a.assignment_id),r=find('resources',assignment?.resource_id);openDialog('📖 Bài làm của '+title('students',a.student_id),`<h3>${esc(r?.title||'Bài học')}</h3><p class="muted tiny">Gửi lúc ${stamp(a.created,true)}</p>${a.total?`<div class="note">Kết quả: ${a.score}/${a.total} câu đúng</div>`:''}${r?.questions.map((q,i)=>`<div class="activity"><span class="badge">${i+1}</span><div><strong>${esc(q.question)}</strong><p>Con chọn: ${esc(q.options[a.answers[i]]??'Chưa trả lời')}</p>${teacher()?`<small>Đáp án đúng: ${esc(q.options[q.answer])}</small>`:''}</div></div>`).join('')||''}${a.response?`<div class="article pre">${esc(a.response)}</div>`:''}${fileLink(a.file_id)}${a.review?`<div class="review-box"><strong>💗 Nhận xét</strong><p class="pre">${esc(a.review)}</p></div>`:''}`)}
async function resourceContent(r){let html=`<p class="muted">${esc(r.description)}</p>`;if(r.type==='text'){let txt=r.body||'';if(r.file_id){const response=await fetch('/api/files/'+encodeURIComponent(r.file_id));if(!response.ok)throw Error('Không đọc được tệp bài học.');const extra=await response.text();txt+=(txt?'\n\n':'')+extra.replace(/^\uFEFF/,'')}html+=`<div class="article pre">${esc(txt)}</div>`}if(r.type==='audio')html+=`<audio controls preload="metadata" class="media audio" src="/api/files/${encodeURIComponent(r.file_id)}">Trình duyệt chưa hỗ trợ phát MP3.</audio>`;if(r.type==='video')html+=`<video controls playsinline preload="metadata" class="media" src="/api/files/${encodeURIComponent(r.file_id)}">Trình duyệt chưa hỗ trợ phát MP4.</video>`;return html+(r.file_id?fileLink(r.file_id):'')}
async function preview(id){const r=find('resources',id);if(!r)return;if(r.type==='quiz'){quiz={resource:r,assignment:null,student:null,answers:r.questions.map(()=>null),index:0};openDialog('🎮 Chơi thử · '+r.title,'');renderQuiz();return}openDialog('📖 '+r.title,'<div class="loading">Đang mở bài học…</div>');try{body.innerHTML=await resourceContent(r)+`<div class="note">Đây là xem thử, không ghi nhận bài làm. Phụ huynh mở bài từ mục Bài cô giao để gửi kết quả.</div>`}catch(e){body.innerHTML=`<p>${esc(e.message)}</p>`}}
function openAssignment(id){const a=find('assignments',id),r=find('resources',a?.resource_id);if(!a||!r)return;const kids=state.students.filter(s=>s.class_id===a.class_id&&(!a.student_id||a.student_id===s.id));if(!kids.length)return toast('Chưa có học sinh phù hợp. Liên hệ cô để liên kết.',true);openDialog('📚 '+r.title,`<div class="stack"><div class="note">${esc(a.instructions||'Bố mẹ đồng hành cùng con nhé!')}<br>Hạn hoàn thành: ${esc(dueLabel(a.due))}</div>${select('student_id','Bé nào đang học?',kids,kids.length===1?kids[0].id:'')}<button class="btn blue" data-action="begin-assignment" data-id="${a.id}">${r.type==='quiz'?'🎮 Bắt đầu chơi':'📖 Mở bài học'}</button></div>`)}
async function beginAssignment(id){const a=find('assignments',id),r=find('resources',a.resource_id),student=$('[name=student_id]',body)?.value;if(!student)return toast('Bố mẹ chọn con đang học trước nhé.',true);if(r.type==='quiz'){quiz={resource:r,assignment:a,student,answers:r.questions.map(()=>null),index:0};$('#dialog-title').textContent='🎮 '+r.title;renderQuiz();return}body.innerHTML='<div class="loading">Đang mở bài học…</div>';try{body.innerHTML=await resourceContent(r)+`<form id="submission-form" class="stack"><div class="note">👧 ${esc(title('students',student))} · Bố mẹ ghi câu trả lời, chia sẻ hoạt động của con hoặc đính kèm bài làm.</div>${area('response','Bài làm / lời chia sẻ của bé','',false,10000)}<label>Đính kèm bài làm (không bắt buộc)<input type="file" name="attachment" accept=".txt,.mp3,.mp4,.png,.jpg,.jpeg,.pdf"><span class="hint">TXT, MP3, MP4, PNG, JPG, PDF · Tối đa 25 MB</span></label><div class="form-error" role="alert"></div><button class="btn" type="submit">💌 Gửi bài cho cô</button></form>`;const form=$('#submission-form');form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{let file=$('[name=attachment]',form).files[0],file_id=file?(await upload(file)).id:null;await api('attempts',{assignment_id:id,student_id:student,response:new FormData(form).get('response'),file_id});body.innerHTML=`<div class="quiz-screen"><div class="quiz-scene">💌 🌟</div><h2>Cô đã nhận được bài của con!</h2><p>Cảm ơn gia đình đã đồng hành cùng bé.</p><button class="btn blue" data-action="close">Hoàn thành</button></div>`;await load();toast('Đã gửi bài cho cô!')})}}catch(e){body.innerHTML=`<p>${esc(e.message)}</p>`}}
function renderQuiz(){const q=quiz.resource.questions[quiz.index];body.innerHTML=`<div class="quiz-screen"><div class="flex between"><span class="badge pink">${quiz.assignment?'👧 '+esc(title('students',quiz.student)):'Chơi thử · Không lưu kết quả'}</span><span class="muted tiny">Câu ${quiz.index+1}/${quiz.answers.length}</span></div><progress class="quiz-meter" max="${quiz.answers.length}" value="${quiz.index+1}" aria-label="Tiến độ câu hỏi"></progress><div class="quiz-scene">${quiz.resource.title.toLowerCase().includes('ong')?'🐝 🌼 🌷':'🌈 🧩 🌟'}</div><h3 class="quiz-question">${esc(q.question)}</h3><div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${quiz.answers[quiz.index]===i?'selected':''}" data-action="quiz-choice" data-id="${i}">${esc(o)}</button>`).join('')}</div><div class="quiz-controls">${quiz.index?btn('← Câu trước','quiz-prev','','ghost'):'<span></span>'}<small>Bé chạm để chọn đáp án nhé!</small>${btn(quiz.index===quiz.answers.length-1?'Hoàn thành 🌟':'Câu tiếp →',quiz.index===quiz.answers.length-1?'quiz-submit':'quiz-next','','blue')}</div></div>`}
async function submitQuiz(button){if(quiz.answers.some(x=>x===null))return toast('Bé hãy chọn đáp án cho tất cả câu hỏi nhé.',true);button.disabled=true;try{let result;if(quiz.assignment){result=await api('attempts',{play_id:quiz.play_id,answers:quiz.answers});await load()}else if(teacher()){result={score:quiz.answers.reduce((n,a,i)=>n+(a===quiz.resource.questions[i].answer?1:0),0),total:quiz.answers.length}}else result={score:null,total:null};body.innerHTML=`<div class="quiz-screen"><div class="quiz-scene">🎉 🌟 🎈</div><h2>Bé đã hoàn thành rồi!</h2>${result.total?`<div class="quiz-score">${result.score}/${result.total}</div><p>Mỗi lần thử là một lần khám phá thêm điều mới.</p>`:'<p>Cảm ơn bé đã tham gia trò chơi!</p>'}<div class="note">${quiz.assignment?'💌 Kết quả đã được gửi cho cô. Cô sẽ sớm gửi lời động viên đến bé.':'Đây là lượt chơi thử, không lưu vào kết quả học tập.'}</div><div class="form-actions"><button class="btn blue" data-action="close">Hoàn thành</button></div></div>`;quiz=null}catch(e){toast(e.message,true);button.disabled=false}}
function exportResults(){const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const lines=[['Học sinh','Mã HS','Lớp','Bài tập','Thời gian','Đúng','Tổng','Nhận xét','Sao','Thời gian làm (giây)','Nguồn điểm','Đã xác nhận'],...state.attempts.map(a=>{const s=find('students',a.student_id),r=find('resources',find('assignments',a.assignment_id)?.resource_id);return [s?.name,s?.code,title('classes',s?.class_id),r?.title,stamp(a.created,true),a.score,a.total,a.review,a.stars,a.duration,a.source,a.trusted?'Có':'Chưa']})];const blob=new Blob(['\uFEFF'+lines.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='Ket_qua_hoc_tap.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
async function notifications(){const notes=[...state.notifications];openDialog('🔔 Thông báo của bạn',`<div class="stack">${notes.map(n=>`<button class="notify-item ${n.read_at?'':'unread'}" data-action="notification-open" data-id="${esc(n.target)}"><span class="avatar">${n.target==='messages'?'💬':n.target==='results'?'💗':'📨'}</span><span><p>${esc(n.title)}</p><small>${stamp(n.created)}</small></span></button>`).join('')||empty('🔔','Bạn đã xem hết thông báo rồi')}</div>`);await api('notifications/read',{});await load(false);updateBell()}
async function removeObject(table,id,label){const object=find(table,id);openDialog('Xác nhận xóa',`<p>Cô muốn xóa ${label} <strong>${esc(object?.name||object?.title||'đã chọn')}</strong>?</p><div class="note warm">Dữ liệu đang liên kết với hồ sơ hoặc bài làm sẽ được giữ lại. Hệ thống sẽ báo nếu không thể xóa.</div><div class="form-actions">${btn('Hủy','close','','ghost')}${btn('Xác nhận xóa','confirm-delete',id,'danger')}</div>`);$('[data-action=confirm-delete]',body).onclick=async e=>{e.stopPropagation();const b=e.currentTarget;b.disabled=true;try{await api('delete',{table,id});dialog.close();await load();toast('Đã xóa dữ liệu')}catch(err){toast(err.message,true);b.disabled=false}}}
async function handleAction(button){const action=button.dataset.action,id=button.dataset.id;try{
if(action?.startsWith('go-'))return navigate(action.slice(3));
if(action==='menu')return $('#sidebar').classList.toggle('open');
if(action==='close'){dialog.close();quiz=null;return}
if(action==='refresh'){await load();toast('Đã cập nhật dữ liệu');return}
if(action==='demo'){button.disabled=true;try{await api('demo/start',{});page='home';await load();startPolling()}finally{button.disabled=false}return}
if(action==='switch'){if(button.dataset.role===state.user.role)return;await api('demo/switch',{role:button.dataset.role});page='home';selectedChat='';await load();return}
if(action==='logout'){await api('logout',{});state=null;page='home';selectedChat='';stopPolling();showLogin();return}
if(action==='class-new'||action==='class-edit')return classEditor(id);
if(action==='class-students'){page='students';filter=id;search='';return renderApp()}
if(action==='student-new'||action==='student-edit')return studentEditor(id);
if(action==='parent-new'||action==='parent-edit')return parentEditor(id);
if(action==='parent-reset')return parentReset(id);
if(action==='resource-new'||action==='resource-edit')return resourceEditor(id);
if(action==='question-add'){captureResourceFields();if(resourceDraft.questions.length>=30)return toast('Tối đa 30 câu hỏi.',true);resourceDraft.questions.push({question:'',options:['','',''],answer:0});return drawResourceFields()}
if(action==='question-remove'){captureResourceFields();resourceDraft.questions.splice(Number(id),1);return drawResourceFields()}
if(action==='filter-resource'){filter=id;return renderResources()}
if(action==='assign')return assignEditor(id);
if(action==='news-new'||action==='news-edit')return newsEditor(id);
if(action==='review')return reviewEditor(id);
if(action==='preview')return preview(id);
if(action==='preview-assignment')return preview(find('assignments',id)?.resource_id);
if(action==='attempt-detail')return attemptDetail(id);
if(action==='open-assignment')return openAssignment(id);
if(action==='begin-assignment')return beginAssignment(id);
if(action==='quiz-choice'){quiz.answers[quiz.index]=Number(id);return renderQuiz()}
if(action==='quiz-next'){if(quiz.answers[quiz.index]===null)return toast('Bé chọn một đáp án trước nhé.',true);quiz.index++;return renderQuiz()}
if(action==='quiz-prev'){quiz.index--;return renderQuiz()}
if(action==='quiz-submit')return submitQuiz(button);
if(action==='chat'){selectedChat=id;page='messages';return renderApp()}
if(action==='notifications')return notifications();
if(action==='notification-open'){dialog.close();return navigate(id)}
if(action==='export-results')return exportResults();
if(action==='password')return modalForm('🔐 Đổi mật khẩu',field('old','Mật khẩu hiện tại','','password')+field('password','Mật khẩu mới','','password','Ít nhất 10 ký tự. Các phiên khác sẽ đăng xuất.'),d=>api('password',d),'Đổi mật khẩu');
if(action==='school')return modalForm('🏫 Tên trường',field('name','Tên trường / phân hiệu',state.school),d=>api('school',d));
const deletions={'delete-class':['classes','lớp học'],'delete-student':['students','học sinh'],'delete-resource':['resources','học liệu'],'delete-assignment':['assignments','bài đã giao'],'delete-news':['news','thông báo']};
if(deletions[action])return removeObject(deletions[action][0],id,deletions[action][1]);
}catch(e){toast(e.message,true)}}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){navigate(p.dataset.page);return}const b=e.target.closest('[data-action]');if(b&&!b.disabled)handleAction(b).catch(e=>toast(e.message,true))});

/* V3: role-based school management, AI authoring, multimedia and integrated games. */
navItems=function(){return nav.filter(([p])=>isAdmin()?true:teacher()?p!=='teachers':!['school','grades','classes','teachers','resources','library'].includes(p)).map(([p,e,n])=>[p,e,!teacher()&&p==='students'?'Con của tôi':!teacher()&&p==='assignments'?'Bài cô giao':n])};
renderApp=function(){if(!state)return showLogin();app.innerHTML=`${state.user.demo?`<div class="demo-bar"><strong>🏆 GIÁM KHẢO TRẢI NGHIỆM</strong><span>${roleName()} · Dữ liệu mẫu riêng</span>${[['admin','👑 Admin'],['teacher','👩‍🏫 Giáo viên'],['parent','👨‍👩‍👧 Phụ huynh']].map(([role,label])=>`<button class="btn small ${role===state.user.role?'blue':'outline'}" data-action="switch" data-role="${role}">${label}</button>`).join('')}<select id="demo-parent" class="demo-select" aria-label="Chọn gia đình trải nghiệm"><option value="">Chọn gia đình khác…</option>${state.demo_parents.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>`:''}<header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Mở menu">☰</button>${brand()}<div class="top-slogan"><span>Mỗi ngày đến lớp<br>là một ngày vui! 🌈</span></div><div class="spacer"></div><button class="icon-btn bell" data-action="notifications" aria-label="Thông báo">🔔${countUnread()?`<em>${countUnread()}</em>`:''}</button><div class="profile"><span class="avatar">${isAdmin()?'👑':teacher()?'👩‍🏫':'👨‍👩‍👧'}</span><div><small>${roleName()}</small><strong>${esc(state.user.name)}</strong></div></div><button class="icon-btn" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">↪</button></header><aside class="sidebar" id="sidebar"><div class="nav-label">CÙNG BÉ KHÁM PHÁ</div><nav>${navItems().map(([p,e,n])=>`<button class="nav-item ${page===p?'active':''}" data-page="${p}"><span class="emoji">${e}</span>${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-garden"></div><div class="sidebar-tip">💗 Mỗi lời động viên là một hạt mầm yêu thương.</div></div></aside><main class="main"><div id="page"></div><footer class="footer">${esc(state.school)} · Học nào bé ơi! V4 ☀️</footer></main>`;renderPage();const dp=$('#demo-parent');if(dp)dp.onchange=async e=>{if(!e.target.value)return;try{await api('demo/switch',{role:'parent',user_id:e.target.value});page='home';selectedChat='';await load()}catch(e){toast(e.message,true)}}};
const renderPageOld=renderPage;
renderPage=function(){if(!state)return;const el=$('#page');if(!el)return;$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));
if(page==='school'){el.innerHTML=pageHead('🏫 Trường / Năm học','Thông tin nhà trường và các năm học.',isAdmin()?btn('✏️ Sửa thông tin trường','school'):'')+`<section class="panel school-banner"><div><span class="badge green">NGÔI TRƯỜNG CỦA BÉ</span><h2>${esc(state.school)}</h2><p>📍 ${esc(state.school_info.address||'Chưa cập nhật địa chỉ')}</p><p>☎ ${esc(state.school_info.phone||'Chưa cập nhật số điện thoại')} · Hiệu trưởng: ${esc(state.school_info.principal||'Chưa cập nhật')}</p></div></section><section class="panel"><div class="section-head"><h2>📅 Năm học</h2>${isAdmin()?btn('＋ Thêm năm học','year-new'):''}</div><div class="grid">${state.years.map(y=>`<article class="year-card"><span class="badge ${y.active?'green':''}">${y.active?'Đang sử dụng':'Đã lưu'}</span><h3>${esc(y.name)}</h3>${isAdmin()?btn('Chỉnh sửa','year-edit',y.id,'small outline'):''}</article>`).join('')}</div></section>`;return}
if(page==='grades'){el.innerHTML=pageHead('🧸 Khối học','Bốn nhóm độ tuổi trong ngôi trường của bé.',isAdmin()?btn('＋ Thêm khối','grade-new'):'')+`<div class="grid grade-grid">${state.grades.map((g,i)=>`<article class="panel grade-card"><span class="grade-icon">${['🍼','🧸','🎨','🎒'][i%4]}</span><h2>${esc(g.name)}</h2><span class="badge">${esc(g.age)}</span><p>${state.classes.filter(c=>c.grade_id===g.id).length} lớp học</p><div class="flex">${btn('Xem các lớp','grade-classes',g.id,'outline')}${isAdmin()?btn('Sửa','grade-edit',g.id,'ghost'):''}</div></article>`).join('')}</div>`;return}
if(page==='classes'){let cls=state.classes.filter(c=>filter==='all'||c.grade_id===filter);el.innerHTML=pageHead('🏡 Lớp học','Tạo lớp, chọn khối, năm học và giáo viên phụ trách.',btn('＋ Thêm lớp','class-new'))+`<div class="filterbar">${select('grade-filter','Khối học',state.grades,filter==='all'?'':filter,'Tất cả khối',false)}</div><div class="grid">${cls.map(c=>`<article class="panel"><div class="flex between"><span class="avatar">🏡</span><span class="badge">${esc(title('grades',c.grade_id))}</span></div><h2>${esc(c.name)}</h2><p>${esc(c.year)} · ${esc(c.age)}</p><p class="muted">👩‍🏫 ${esc(title('teachers',c.teacher_id)==='—'?'Chưa phân công giáo viên':title('teachers',c.teacher_id))}</p><p><strong>${state.students.filter(s=>s.class_id===c.id).length}</strong> học sinh</p><div class="flex">${btn('Danh sách trẻ','class-students',c.id,'blue small')}${btn('Sửa','class-edit',c.id,'ghost small')}${btn('Xóa','delete-class',c.id,'danger small')}</div></article>`).join('')||empty('🏡','Chưa có lớp phù hợp')}</div>`;$('[name=grade-filter]').onchange=e=>{filter=e.target.value||'all';renderPage()};return}
if(page==='teachers'){el.innerHTML=pageHead('👩‍🏫 Giáo viên','Admin tự đặt tên đăng nhập, mật khẩu và phân công lớp.',btn('＋ Cấp tài khoản giáo viên','teacher-new'))+`<div class="panel table-wrap"><table><thead><tr><th>Giáo viên</th><th>Tên đăng nhập</th><th>Lớp được phân công</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${state.teachers.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td><code>${esc(t.username)}</code></td><td>${state.classes.filter(c=>c.teacher_id===t.id).map(c=>esc(c.name)).join(', ')||'Chưa phân công'}</td><td><span class="badge ${t.active?'green':'pink'}">${t.active?'Hoạt động':'Tạm khóa'}</span></td><td><div class="flex">${btn('Sửa tên','teacher-edit',t.id,'small ghost')}${btn('Đổi mật khẩu','teacher-reset',t.id,'small outline')}${btn(t.active?'Tạm khóa':'Mở khóa','teacher-status',t.id,'small ghost')}</div></td></tr>`).join('')}</tbody></table>${state.teachers.length?'':empty('👩‍🏫','Chưa có tài khoản giáo viên')}</div><div class="note">Sau khi tạo tài khoản, vào Lớp học → Sửa để phân công lớp cho giáo viên. Một giáo viên có thể phụ trách nhiều lớp.</div>`;return}
if(page==='students'){el.innerHTML=pageHead(teacher()?'👨‍👩‍👧 Học sinh / Phụ huynh':'👧 Con của tôi',isAdmin()?'Thêm học sinh: hệ thống tự tạo mã và mật khẩu là 4 số cuối của mã.':'Hồ sơ và tài khoản gia đình được liên kết với từng trẻ.',isAdmin()?btn('＋ Thêm học sinh','student-new'):'')+`<div class="filterbar"><select id="student-class-filter" aria-label="Lọc theo lớp"><option value="all">Tất cả lớp</option>${state.classes.map(c=>`<option value="${c.id}" ${filter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><input class="search" id="student-search" aria-label="Tìm học sinh" placeholder="Tìm tên hoặc mã học sinh…" value="${esc(search)}"></div><div id="students-list" class="panel table-wrap"></div>`;renderStudents();$('#student-class-filter').onchange=e=>{filter=e.target.value;renderStudents()};$('#student-search').oninput=e=>{search=e.target.value;renderStudents()};return}
if(['resources','library','stories','music'].includes(page)){const category=page==='stories'?'stories':page==='music'?'music':'games';const heading=page==='resources'?'🛠️ Game và bài tập':page==='library'?'🎮 Kho game học mà chơi':page==='stories'?'📖 Nghe thơ truyện cùng bé':'🎵 Giai điệu của bé';el.innerHTML=pageHead(heading,category==='games'?'Học liệu tạo xong được lưu tại kho game, sẵn sàng chơi thử và giao bài.':'Thư viện MP3 và MP4 để gia đình nghe, xem cùng bé.',teacher()?btn(category==='games'?'＋ Tạo / Tải game':'＋ Tải MP3 / MP4','resource-new'):'')+`${teacher()&&category==='games'?`<section class="panel author-tools"><div class="tabs">${[['quiz','✍️ Tạo thủ công'],['html','📤 Tải game HTML'],['audio','🎵 MP3'],['video','🎬 MP4'],['link','🔗 Dán link game'],['ai','✨ Tạo game AI'],['json','📋 Nhập JSON']].map(([id,label])=>btn(label,id==='ai'?'ai-editor':id==='json'?'json-import':'resource-type',id,'outline')).join('')}</div><p class="muted">Game ngoài chỉ tự gửi điểm nếu hỗ trợ giao thức kết nối của ứng dụng. Game không hỗ trợ vẫn mở được nhưng không tự có điểm.</p></section>`:''}<section class="panel"><div class="filterbar"><div class="tabs">${[['all','Tất cả'],['quiz','Trò chơi'],['audio','MP3'],['video','MP4'],['text','Văn bản'],['html','HTML'],['link','Liên kết']].filter(([id])=>category==='games'||['all','audio','video'].includes(id)).map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-action="filter-resource" data-id="${id}">${label}</button>`).join('')}</div><input id="resource-search" class="search" placeholder="Tìm học liệu…" aria-label="Tìm học liệu" value="${esc(search)}"></div><div class="grid" id="resource-list"></div></section>`;renderResources();$('#resource-search').oninput=e=>{search=e.target.value;renderResources()};return}
if(page==='rankings'){const ranking=state.rankings.filter(r=>filter==='all'||r.class_id===filter).map(r=>({...r}));let lastRank=0,lastKey='';ranking.forEach((r,i)=>{const k=[r.completed,r.correct,r.duration].join(':');if(k!==lastKey){lastRank=i+1;lastKey=k}r.viewRank=r.completed?lastRank:null});el.innerHTML=pageHead('🏆 Kết quả thi đua','Ưu tiên số bài hoàn thành → số câu đúng → tổng thời gian thấp hơn.')+`<div class="stats">${[['🏅',state.attempts.filter(a=>a.trusted&&find('assignments',a.assignment_id)?.origin!=='practice').length,'Lượt đã xác nhận'],['🌟',state.attempts.reduce((n,a)=>n+(a.trusted&&find('assignments',a.assignment_id)?.origin!=='practice'?a.score||0:0),0),'Câu trả lời đúng'],['👧',state.students.length,'Học sinh'],['⏱️',state.attempts.reduce((n,a)=>n+(a.trusted&&find('assignments',a.assignment_id)?.origin!=='practice'?a.duration:0),0)+'s','Thời gian ghi nhận']].map(([icon,n,label])=>`<div class="stat"><span class="stat-icon">${icon}</span><div><strong>${n}</strong><small>${label}</small></div></div>`).join('')}</div><div class="filterbar">${select('ranking-class','Lọc theo lớp',state.classes,filter==='all'?'':filter,'Tất cả lớp',false)}</div><div class="panel table-wrap"><table><thead><tr><th>Hạng</th><th>Học sinh</th><th>Lớp</th><th>Bài hoàn thành</th><th>Số câu đúng</th><th>Tổng thời gian</th></tr></thead><tbody>${ranking.map((r,i)=>`<tr class="${r.mine?'my-rank':''}"><td><strong>${r.viewRank?(['🥇','🥈','🥉'][r.viewRank-1]||'#'+r.viewRank):'—'}</strong></td><td><strong>${esc(r.name)}</strong>${r.mine?' 💗':''}</td><td>${esc(title('classes',r.class_id))}</td><td>${r.completed}</td><td>${r.correct}/${r.total}</td><td>${durationLabel(r.duration)}</td></tr>`).join('')}</tbody></table>${ranking.length?'':empty('🏆','Chưa có dữ liệu thi đua')}</div><div class="note warm">Mỗi bài chỉ lấy lượt làm có số câu đúng cao nhất, rồi thời gian ngắn nhất. Điểm do game ngoài gửi cần cô xác nhận trước khi vào thi đua. Thời gian tính từ lúc mở bài đến khi gửi, có thể gồm cả lúc bé nghỉ.</div>`;$('[name=ranking-class]').onchange=e=>{filter=e.target.value||'all';renderPage()};return}
if(page==='comments'){el.innerHTML=pageHead('💗 Nhận xét của cô',teacher()?'Ghi nhận xét theo danh sách lớp hoặc nhắn riêng cho từng gia đình.':'Những lời động viên dành riêng cho con.',teacher()?btn('✍️ Nhận xét theo lớp','class-comment'):'')+`<div class="stack">${state.class_reviews.map(r=>`<article class="panel"><span class="badge pink">👧 ${esc(title('students',r.student_id))}</span><h3>${esc(r.teacher_name)}</h3><p class="pre">${esc(r.body)}</p><small>${stamp(r.created,true)}</small></article>`).join('')||empty('💗','Chưa có nhận xét theo lớp')}${state.attempts.filter(a=>a.review).slice(0,15).map(a=>`<article class="panel"><span class="badge">Bài học · ${esc(title('students',a.student_id))}</span><p class="pre">${esc(a.review)}</p><small>${stamp(a.reviewed)}</small></article>`).join('')}</div><div class="form-actions">${btn('💬 Trao đổi riêng','go-messages','','blue')}</div>`;return}
if(page==='news'){el.innerHTML=pageHead('📣 Thông báo của cô','Thông báo nhà trường và lớp học, có thể đính kèm hình ảnh.',teacher()?btn('＋ Đăng thông báo','news-new'):'')+state.news.map(n=>`<article class="news-card"><div class="flex between"><span class="badge">${n.class_id?'🏡 '+esc(title('classes',n.class_id)):'🏫 Toàn trường'}</span><small>${stamp(n.created)}</small></div><h2>${esc(n.title)}</h2><div class="pre">${esc(n.body)}</div>${n.file_id?`<img class="news-image" src="/api/files/${encodeURIComponent(n.file_id)}" alt="Hình ảnh đính kèm thông báo" loading="lazy">${fileLink(n.file_id)}`:''}${teacher()&&(isAdmin()||n.creator_id===state.user.id)?`<div class="card-actions">${btn('Sửa','news-edit',n.id,'small ghost')}${btn('Xóa','delete-news',n.id,'small danger')}</div>`:''}</article>`).join('')+(state.news.length?'':empty('📣','Chưa có thông báo'));return}
if(page==='settings'){el.innerHTML=pageHead('⚙️ Cài đặt','Thông tin tài khoản và cấu hình dịch vụ AI.')+`<div class="two-col"><section class="panel"><h2>👤 ${esc(state.user.name)}</h2><p><code>${esc(state.user.username)}</code> · ${roleName()}</p>${btn('Đổi mật khẩu','password','','outline')}<p class="muted">${teacher()?'':'Mật khẩu ban đầu của tài khoản mới là 4 số cuối mã học sinh. Gia đình nên đổi sau lần đăng nhập đầu.'}</p></section><section class="panel"><h2>✨ Tạo game AI</h2><span class="badge ${state.ai.configured?'green':'yellow'}">${state.ai.configured?'Đã cấu hình dịch vụ':'Chưa cấu hình API'}</span><p>AI tạo bộ câu hỏi nháp; cô kiểm tra rồi lưu vào kho. Không tự đăng học liệu chưa được duyệt.</p>${isAdmin()?btn('Cấu hình API AI','ai-settings','','outline'):''}</section></div><section class="panel"><h2>🔗 Kết nối game ngoài</h2><p>Game hỗ trợ gửi kết quả qua postMessage có thể kết nối với hệ thống. Tệp mẫu và hướng dẫn nằm trong thư mục <code>samples</code> và tài liệu <code>KET_NOI_GAME.md</code>.</p><div class="note">Một liên kết thông thường không tự cung cấp điểm. Website ngoài có thể chặn nhúng; khi đó dùng nút Mở trang game, và không ghi điểm tự động.</div></section>`;return}
renderPageOld();
};
function durationLabel(s){s=Number(s)||0;return s<60?s+' giây':Math.floor(s/60)+' phút '+s%60+' giây'}
renderResources=function(){const category=page==='stories'?'stories':page==='music'?'music':'games';const items=state.resources.filter(r=>r.category===category&&(filter==='all'||r.type===filter)&&r.title.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')));$('#resource-list').innerHTML=items.map(resourceCard).join('')||empty(category==='games'?'🎮':'🎵','Chưa có học liệu phù hợp');$$('.tab').forEach(t=>t.classList.toggle('active',t.dataset.id===filter))};
const resourceCardOld=resourceCard;resourceCard=function(r,i=0){let html=resourceCardOld(r,i);if(teacher()&&!isAdmin()&&r.creator_id!==state.user.id)html=html.replace(/<button[^>]*data-action="resource-edit"[\s\S]*?<\/button>/g,'').replace(/<button[^>]*data-action="delete-resource"[\s\S]*?<\/button>/g,'');return html.replace('class="card-art"','class="card-art"').replace('</h3>',`</h3>${r.type==='html'||r.type==='link'?`<span class="badge ${r.integration?'green':'yellow'}">${r.integration?'Có giao thức nhận điểm':'Chỉ mở game, chưa nhận điểm'}</span>`:''}`)};
renderStudents=function(){let kids=state.students.filter(s=>(filter==='all'||s.class_id===filter)&&(s.name+' '+s.code).toLowerCase().includes(search.toLowerCase()));$('#students-list').innerHTML=kids.length?`<table><thead><tr><th>Học sinh</th><th>Mã học sinh</th><th>Lớp</th><th>Tài khoản gia đình</th><th>Thao tác</th></tr></thead><tbody>${kids.map(s=>`<tr><td><strong>${esc(s.name)}</strong><p class="muted">${esc(s.birthday||'')}</p></td><td><code>${esc(s.code)}</code></td><td>${esc(title('classes',s.class_id))}</td><td>${teacher()?`<code>${esc(find('parents',s.parent_id)?.username||s.code)}</code>`:'Tài khoản hiện tại'}</td><td><div class="flex">${isAdmin()?btn('Sửa','student-edit',s.id,'small ghost')+btn('Đặt lại mật khẩu','parent-reset',s.parent_id,'small outline')+btn('Xóa','delete-student',s.id,'small danger'):''}${teacher()?btn('Nhắn gia đình','chat',s.parent_id,'small blue'):btn('Xem bài','go-assignments','','small blue')}</div></td></tr>`).join('')}</tbody></table>`:empty('👧','Chưa có học sinh phù hợp',isAdmin()?'Bấm Thêm học sinh để tự tạo mã và tài khoản.':'Liên hệ admin để phân công hoặc liên kết hồ sơ.')};
const renderResultsOld=renderResults;renderResults=function(){renderResultsOld();$$('.result-card').forEach((card,i)=>{const a=state.attempts.filter(a=>filter==='all'||a.student_id===filter)[i];if(a){const note=document.createElement('div');note.className='note';note.textContent='⏱ '+durationLabel(a.duration)+(a.source==='external'?(a.trusted?' · Điểm game ngoài, đã được cô xác nhận':' · Điểm game ngoài gửi, chờ cô xác nhận'):' · Bài trong hệ thống');card.prepend(note);if(a.source==='external')$$('p',card).filter(x=>x.textContent.includes('Kết quả chấm tự động')).forEach(p=>p.textContent=a.total+' câu · Game bên ngoài báo kết quả; chưa phải điểm chấm trực tiếp bởi hệ thống.')}})};
classEditor=function(id){const c=find('classes',id)||{};modalForm(id?'✏️ Sửa lớp học':'🏡 Thêm lớp học',`<div class="form-grid">${field('name','Tên lớp',c.name||'')}${select('grade_id','Khối học',state.grades,c.grade_id||'')}${select('year','Năm học',state.years.map(y=>({id:y.name,name:y.name})),c.year||state.years.find(y=>y.active)?.name||'',null)}${isAdmin()?select('teacher_id','Giáo viên phụ trách',state.teachers.filter(t=>t.active),c.teacher_id||'','Chưa phân công',false):'<div class="note">Lớp mới được phân công cho tài khoản giáo viên hiện tại.</div>'}</div>`,d=>api('classes',{...d,id}))};
function yearEditor(id){const y=find('years',id)||{};modalForm(id?'Sửa năm học':'📅 Thêm năm học',field('name','Tên năm học',y.name||'2026–2027')+`<label class="check-label"><input type="checkbox" name="active" ${y.active||!id?'checked':''}> Đặt làm năm học đang sử dụng</label>`,d=>api('years',{...d,id,active:!!d.active}))}
function gradeEditor(id){const g=find('grades',id)||{};modalForm(id?'Sửa khối học':'🧸 Thêm khối học',field('name','Tên khối',g.name||'')+field('age','Độ tuổi',g.age||''),d=>api('grades',{...d,id}))}
function teacherEditor(id){const t=find('teachers',id)||{};modalForm(id?'Sửa tên giáo viên':'👩‍🏫 Cấp tài khoản giáo viên',field('name','Họ và tên',t.name||'')+(id?'':field('username','Tên đăng nhập','','text','Chữ thường không dấu, số, . _ -')+field('password','Mật khẩu','','password','Ít nhất 10 ký tự. Giáo viên có thể đổi sau khi đăng nhập.')),d=>api('teachers',{...d,id}))}
function teacherReset(id){modalForm('Đặt lại mật khẩu giáo viên',field('password','Mật khẩu mới','','password','Ít nhất 10 ký tự.'),d=>api('teachers/reset',{...d,id}))}
studentEditor=function(id){if(!state.classes.length)return toast('Cô hãy tạo lớp trước nhé.',true);const s=find('students',id)||{};const form=modalForm(id?'Sửa hồ sơ học sinh':'👧 Thêm học sinh & tạo tài khoản',`<div class="form-grid">${field('name','Họ và tên học sinh',s.name||'')}${select('class_id','Lớp học',state.classes,s.class_id||'')}${field('birthday','Ngày sinh',s.birthday||'','date','',false)}${id?`<div class="note">Mã học sinh: <strong>${esc(s.code)}</strong></div>`:'<div class="note">Mã học sinh được tự sinh. Mật khẩu ban đầu là 4 số cuối của mã.</div>'}<div class="full">${area('note','Ghi chú',s.note||'',false,1000)}</div></div>`,()=>{});form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{const result=await api('students',{...Object.fromEntries(new FormData(form)),id});dialog.close();await load();if(result.credentials)openDialog('✅ Đã tạo học sinh và tài khoản gia đình',`<div class="note green-note">Cô gửi riêng thông tin này cho đúng gia đình nhé.</div><h3>${esc(Object.fromEntries(new FormData(form)).name)}</h3><p>Mã / Tên đăng nhập:</p><div class="credential">${esc(result.credentials.username)}</div><p>Mật khẩu ban đầu:</p><div class="credential">${esc(result.credentials.password)}</div><p class="muted">Phụ huynh có thể đổi mật khẩu trong Cài đặt sau khi đăng nhập.</p>${btn('Đã lưu thông tin','close','','blue')}`);else toast('Đã cập nhật học sinh')})}};
parentReset=function(id){const s=state.students.find(s=>s.parent_id===id);modalForm('Đặt lại mật khẩu gia đình',field('password','Mật khẩu mới',s?.code.slice(-4)||'','password','Có thể đặt lại bằng 4 số cuối mã học sinh; phụ huynh nên đổi sau khi đăng nhập.'),d=>api('parents/reset',{...d,id}))};
const drawResourceFieldsOld=drawResourceFields;
drawResourceFields=function(){if(resourceDraft.type==='link'){$('#resource-fields').innerHTML=field('external_url','Đường dẫn game HTTPS',resourceDraft.external_url||'','url','Ví dụ https://...')+`<label class="check-label"><input type="checkbox" name="integration" ${resourceDraft.integration?'checked':''}> Game đã hỗ trợ giao thức gửi kết quả hocnaobeoi:result</label><div class="note warm">Một link thông thường chưa thể tự gửi điểm. Chỉ đánh dấu khi game đã tích hợp theo tài liệu KET_NOI_GAME.md.</div>`;return}if(resourceDraft.type==='html'){$('#resource-fields').innerHTML=`<div class="upload-box">📤 Tải game HTML tự chứa trong một tệp. Tối đa 25 MB.<input name="attachment" type="file" accept=".html" aria-label="Tải game HTML">${resourceDraft.file_id?'<p>📎 Đã có tệp game.</p>':''}</div><label class="check-label"><input type="checkbox" name="integration" ${resourceDraft.integration?'checked':''}> Game hỗ trợ giao thức gửi kết quả</label><div class="note">Có tệp mẫu game đã kết nối tại <code>samples/game-dem-qua.html</code>. Game được mở trong khung cách ly, không được truy cập tài khoản của web.</div>`;return}drawResourceFieldsOld()};
const captureResourceOld=captureResourceFields;captureResourceFields=function(){captureResourceOld();const url=$('[name=external_url]');if(url)resourceDraft.external_url=url.value;const integration=$('[name=integration]');if(integration)resourceDraft.integration=integration.checked};
resourceEditor=function(id,requestedType,requestedCategory){const r=find('resources',id);if(r&&state.assignments.some(a=>a.resource_id===id))return toast('Học liệu đã giao: cô hãy tạo bản mới để giữ lịch sử.',true);const category=requestedCategory||r?.category||(page==='stories'?'stories':page==='music'?'music':'games');resourceDraft=r?structuredClone(r):{title:'',description:'',type:requestedType||(category==='games'?'quiz':'audio'),category,body:'',file_id:null,external_url:'',integration:0,questions:[{question:'',options:['','',''],answer:0}]};const allowed=Object.entries(typeLabel).filter(([t])=>category==='games'||['audio','video'].includes(t));openDialog(r?'Sửa học liệu':'✨ Tạo / Tải học liệu',`<form id="resource-form" class="stack">${field('title','Tên game / bài tập',resourceDraft.title)}${area('description','Lời giới thiệu',resourceDraft.description,false,3000)}<div class="form-grid">${select('type','Loại học liệu',allowed.map(([id,name])=>({id,name})),resourceDraft.type,null)}${select('category','Lưu vào kho',[{id:'games',name:'Kho game học mà chơi'},{id:'stories',name:'Nghe thơ truyện cùng bé'},{id:'music',name:'Giai điệu của bé'}],category,null)}</div><div id="resource-fields"></div><div class="form-error" role="alert"></div><div class="form-actions"><button class="btn ghost" type="button" data-action="close">Hủy</button><button class="btn" type="submit">Lưu vào kho</button></div></form>`);drawResourceFields();const form=$('#resource-form');$('[name=type]',form).onchange=e=>{captureResourceFields();resourceDraft.type=e.target.value;resourceDraft.file_id=null;drawResourceFields()};const cat=$('[name=category]',form);cat.onchange=()=>{captureResourceFields();const allowed=Object.entries(typeLabel).filter(([t])=>cat.value==='games'||['audio','video'].includes(t));if(!allowed.some(([t])=>t===resourceDraft.type)){resourceDraft.type='audio';resourceDraft.file_id=null}const typeSelect=$('[name=type]',form);typeSelect.innerHTML=allowed.map(([id,name])=>`<option value="${id}" ${id===resourceDraft.type?'selected':''}>${esc(name)}</option>`).join('');drawResourceFields()};form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{captureResourceFields();const d=Object.fromEntries(new FormData(form));let file_id=resourceDraft.file_id;const file=$('[name=attachment]',form)?.files[0];if(file)file_id=(await upload(file)).id;const illustration=$('[name=illustration]',form)?.files[0];if(illustration)resourceDraft.illustration_id=(await upload(illustration)).id;await api('resources',{id,title:d.title,description:d.description,type:resourceDraft.type,category:d.category,body:resourceDraft.body,file_id,questions:resourceDraft.type==='quiz'?resourceDraft.questions:[],external_url:resourceDraft.external_url||'',integration:!!resourceDraft.integration,theme:d.theme||'auto',illustration_id:resourceDraft.illustration_id||null});dialog.close();await load();toast('Đã lưu học liệu vào kho. Cô có thể xem thử và giao bài ngay!')})}};
assignEditor=function(resourceId){if(!state.classes.length||!state.resources.length)return toast('Cần có lớp và học liệu trước khi giao bài.',true);const options=[{id:'class',name:'Cả lớp'},{id:'student',name:'Cá nhân học sinh'},...(isAdmin()?[{id:'school',name:'Toàn trường'}]:[])];const form=modalForm('📨 Giao bài tập',select('resource_id','Học liệu',state.resources,resourceId||'')+select('scope','Phạm vi giao bài',options,'class',null)+`<div id="assignment-class">${select('class_id','Chọn lớp',state.classes,'')}</div><div id="assignment-student" hidden>${select('student_id','Chọn học sinh',state.students,'')}</div>`+field('due','Hạn hoàn thành','','date','Có thể nộp sau hạn; cô theo dõi ngày gửi.',false)+area('instructions','Lời dặn','Bố mẹ đồng hành và để bé tự khám phá nhé!',false,3000),d=>api('assignments',d),'Giao bài & thông báo gia đình');const update=()=>{let scope=$('[name=scope]',form).value;$('#assignment-class').hidden=scope!=='class';$('#assignment-student').hidden=scope!=='student';$('[name=class_id]',form).disabled=scope!=='class';$('[name=student_id]',form).disabled=scope!=='student'};$('[name=scope]',form).onchange=update;update()};
newsEditor=function(id){const n=find('news',id)||{};modalForm(id?'Sửa thông báo':'📣 Đăng thông báo',field('title','Tiêu đề',n.title||'')+select('class_id','Phạm vi',state.classes,n.class_id||'',isAdmin()?'Toàn trường':'Chọn lớp',!isAdmin())+area('body','Nội dung',n.body||'',true,10000)+`<label>Ảnh đính kèm (không bắt buộc)<input name="image" type="file" accept=".jpg,.jpeg,.png"><span class="hint">PNG, JPG · Tối đa 25 MB. ${n.file_id?'Thông báo hiện đã có ảnh.':''}</span></label>`,async(d,form)=>{let f=$('[name=image]',form).files[0],file_id=f?(await upload(f)).id:n.file_id;return api('news',{title:d.title,body:d.body,class_id:d.class_id,id,file_id})},'Đăng & thông báo')};
reviewEditor=function(id){const a=find('attempts',id);modalForm('💗 Nhận xét cho '+title('students',a.student_id),area('review','Lời nhận xét',a.review||'',true,5000)+select('stars','Sao động viên',[{id:'0',name:'Không gắn sao'},...Array.from({length:5},(_,i)=>({id:String(i+1),name:'★'.repeat(i+1)}))],String(a.stars),null)+(a.source==='external'?`<label class="check-label"><input type="checkbox" name="accept_external" ${a.trusted?'checked':''}> Tôi đã kiểm tra kết quả game ngoài và xác nhận đưa vào thi đua</label>`:''),d=>api('reviews',{id,review:d.review,stars:Number(d.stars),accept_external:!!d.accept_external}),'Lưu nhận xét')};
function classComment(){if(!state.classes.length)return toast('Chưa có lớp học.',true);openDialog('💗 Nhận xét theo danh sách lớp',`<form id="class-review-form" class="stack">${select('class_id','Chọn lớp',state.classes,'')}<div id="class-review-list"></div><div class="form-error" role="alert"></div><button class="btn" type="submit">Gửi nhận xét cho các gia đình</button></form>`);const f=$('#class-review-form');$('[name=class_id]',f).onchange=e=>{$('#class-review-list').innerHTML=state.students.filter(s=>s.class_id===e.target.value).map(s=>`<div class="question-editor"><h3>${esc(s.name)} · <code>${esc(s.code)}</code></h3><textarea data-student-review="${s.id}" maxlength="5000" placeholder="Lời động viên dành riêng cho bé…"></textarea></div>`).join('')||empty('👧','Lớp chưa có học sinh')};f.onsubmit=async e=>{e.preventDefault();await runForm(f,async()=>{await api('class-reviews',{class_id:$('[name=class_id]',f).value,entries:$$('[data-student-review]',f).map(x=>({student_id:x.dataset.studentReview,body:x.value})).filter(x=>x.body.trim())});dialog.close();await load();toast('Đã gửi nhận xét đến các gia đình')})}}
function aiSettings(){if(state.user.demo)return toast('Khu trải nghiệm không dùng khóa AI thật của trường.',true);modalForm('✨ Cấu hình dịch vụ AI',`<div class="note">Dùng dịch vụ có API tương thích Chat Completions. Khóa chỉ lưu ở máy chủ, không đưa vào JavaScript. Không nhập khóa vào cuộc trò chuyện.</div>`+field('url','Endpoint HTTPS đầy đủ',state.ai.url||'','url','Địa chỉ nhận yêu cầu chat/completions do nhà cung cấp cấp.')+field('model','Tên model chính xác',state.ai.model||'')+field('key','API key','','password','Để trống để giữ khóa đã lưu.',!state.ai.configured),d=>api('ai/settings',d),'Lưu cấu hình')}
function aiEditor(){openDialog('✨ Tạo game bằng AI',`<form id="ai-form" class="stack"><div class="note">${state.ai.configured&&!state.user.demo?'AI sẽ tạo bản nháp. Cô kiểm tra nội dung và đáp án trước khi lưu.':'Chưa dùng được API trong phiên này. Cô có thể dùng tab Nhập JSON từ công cụ AI của mình.'}</div>${area('topic','Chủ đề và mục tiêu','Nhận biết chữ a, ă, â',true,1500)}<div class="form-grid">${field('age','Độ tuổi','5–6 tuổi')}${field('count','Số câu hỏi',5,'number')}</div><div class="form-error" role="alert"></div><button class="btn" type="submit">✨ Tạo bản nháp bằng AI</button><button class="btn outline" type="button" data-action="json-import">📋 Nhập JSON có sẵn</button></form>`);const form=$('#ai-form');$('[name=count]',form).min='1';$('[name=count]',form).max='20';form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{const d=Object.fromEntries(new FormData(form));toast('Đang tạo bản nháp AI, cô chờ một chút nhé…');const draft=await api('ai/generate',{...d,count:Number(d.count)});openQuizDraft(draft)})}}
function openQuizDraft(draft){if(!draft||!Array.isArray(draft.questions)||!draft.questions.length)throw Error('JSON cần có mảng questions và ít nhất một câu hỏi.');if(draft.questions.some(q=>!q.question||!Array.isArray(q.options)||q.options.length<2||q.options.length>4||!Number.isInteger(q.answer)||q.answer<0||q.answer>=q.options.length))throw Error('Câu hỏi JSON cần question, 2–4 options và answer là vị trí đúng tính từ 0.');resourceEditor(undefined,'quiz','games');resourceDraft.title=draft.title||'Game mới';resourceDraft.description=draft.description||'';resourceDraft.questions=draft.questions;$('#resource-form [name=title]').value=resourceDraft.title;$('#resource-form [name=description]').value=resourceDraft.description;drawResourceFields();toast('Cô kiểm tra câu hỏi và đáp án, rồi bấm Lưu vào kho.')}
function jsonImport(){openDialog('📋 Nhập game JSON',`<form id="json-form" class="stack"><div class="note">Dán bộ câu hỏi do cô hoặc AI chuẩn bị. Mẫu có trong <code>samples/game-mau.json</code>.</div><label>Chọn tệp JSON (không bắt buộc)<input name="jsonfile" type="file" accept=".json"></label>${area('json','Nội dung JSON','',false,100000)}<div class="form-error" role="alert"></div><button class="btn" type="submit">Mở bản nháp để kiểm tra</button></form>`);const form=$('#json-form');form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{const file=$('[name=jsonfile]',form).files[0];let raw=file?await file.text():$('[name=json]',form).value;let draft;try{draft=JSON.parse(raw)}catch{throw Error('Nội dung chưa phải JSON hợp lệ.')}openQuizDraft(draft)})}}
let embeddedContext=null;
dialog.addEventListener('close',()=>{embeddedContext=null;quiz=null});
const previewOld=preview;
preview=async function(id){const r=find('resources',id);if(!r)return;if(['html','link'].includes(r.type))return openEmbeddedGame(r,null);return previewOld(id)};
function openEmbeddedGame(resource,play){const src=resource.type==='html'?'/api/game/'+encodeURIComponent(resource.file_id):resource.external_url;openDialog('🕹️ '+resource.title,`<div class="stack"><div class="note ${resource.integration?'':'warm'}">${play?resource.integration?'Kết quả game gửi sẽ được lưu và chờ cô xác nhận.':'Game này chưa hỗ trợ gửi điểm; chỉ mở trải nghiệm.':'Đang chơi thử, không lưu kết quả học tập.'}</div><iframe id="game-frame" class="game-frame" title="${esc(resource.title)}" sandbox="allow-scripts" referrerpolicy="no-referrer" src="${esc(src)}"></iframe><p id="game-status" class="muted">Chờ game khởi động…</p>${resource.type==='link'?`<a class="btn outline" target="_blank" rel="noopener noreferrer" href="${esc(resource.external_url)}">Mở trang game ↗</a><small>Nếu trang game chặn nhúng, mở riêng để chơi. Kết quả ở cửa sổ riêng không tự kết nối về phiên này.</small>`:''}</div>`);embeddedContext={resource,play,submitted:false};const frame=$('#game-frame');frame.addEventListener('load',()=>{const status=$('#game-status');if(status)status.textContent=resource.integration?'Game đã mở. Chơi xong để gửi kết quả về hệ thống.':'Game đang được mở. Không tự ghi điểm khi chưa có giao thức kết nối.';frame.contentWindow.postMessage({type:'hocnaobeoi:init',nonce:play?.nonce||'',preview:!play},'*')})}
window.addEventListener('message',async event=>{const ctx=embeddedContext,frame=$('#game-frame');if(!ctx||!frame||!dialog.open||event.source!==frame.contentWindow||!event.data||typeof event.data!=='object')return;const d=event.data;if(d.type==='hocnaobeoi:ready'){frame.contentWindow.postMessage({type:'hocnaobeoi:init',nonce:ctx.play?.nonce||'',preview:!ctx.play},'*');return}if(d.type!=='hocnaobeoi:result'||!ctx.play||!ctx.resource.integration||ctx.submitted||d.nonce!==ctx.play.nonce)return;if(!Number.isInteger(d.correct)||!Number.isInteger(d.total)||d.total<1||d.total>1000||d.correct<0||d.correct>d.total)return;ctx.submitted=true;try{const r=await api('external-result',{play_id:ctx.play.play_id,nonce:d.nonce,correct:d.correct,total:d.total});const status=$('#game-status');if(status)status.textContent=`🌟 Đã nhận ${r.score}/${r.total} câu đúng · ${durationLabel(r.duration)}. Chờ cô xác nhận vào thi đua.`;await load();toast('Đã lưu kết quả game bên ngoài.')}catch(e){ctx.submitted=false;toast(e.message,true)}});
beginAssignment=async function(id){const a=find('assignments',id),r=find('resources',a?.resource_id),student=$('[name=student_id]',body)?.value;if(!student)return toast('Bố mẹ chọn con đang học nhé.',true);const button=$('[data-action=begin-assignment]',body);if(button)button.disabled=true;try{const play=await api('plays/start',{assignment_id:id,student_id:student});if(r.type==='quiz'){quiz={resource:r,assignment:a,student,play_id:play.play_id,answers:r.questions.map(()=>null),index:0};$('#dialog-title').textContent='🎮 '+r.title;renderQuiz();return}if(['html','link'].includes(r.type))return openEmbeddedGame(r,play);body.innerHTML='<div class="loading">Đang mở bài học…</div>';body.innerHTML=await resourceContent(r)+`<form id="submission-form" class="stack"><div class="note">👧 ${esc(title('students',student))} · Bố mẹ ghi câu trả lời hoặc đính kèm hoạt động của con.</div>${area('response','Bài làm / chia sẻ của bé','',false,10000)}<label>Tệp bài làm (không bắt buộc)<input type="file" name="attachment" accept=".txt,.mp3,.mp4,.png,.jpg,.jpeg,.pdf"><span class="hint">Tối đa 25 MB</span></label><div class="form-error" role="alert"></div><button class="btn" type="submit">💌 Gửi bài cho cô</button></form>`;const form=$('#submission-form');form.onsubmit=async e=>{e.preventDefault();await runForm(form,async()=>{const file=$('[name=attachment]',form).files[0],file_id=file?(await upload(file)).id:null;await api('attempts',{play_id:play.play_id,response:new FormData(form).get('response'),file_id});body.innerHTML=`<div class="quiz-screen"><div class="quiz-scene">💌 🌟</div><h2>Cô đã nhận bài của con!</h2><p>Cảm ơn gia đình đã đồng hành.</p>${btn('Hoàn thành','close','','blue')}</div>`;await load();toast('Đã gửi bài cho cô')})}}catch(e){toast(e.message,true);if(button)button.disabled=false}};
const handleActionOld=handleAction;
handleAction=async function(button){const action=button.dataset.action,id=button.dataset.id;try{
if(action==='year-new'||action==='year-edit')return yearEditor(id);
if(action==='grade-new'||action==='grade-edit')return gradeEditor(id);
if(action==='grade-classes'){page='classes';filter=id;return renderApp()}
if(action==='teacher-new'||action==='teacher-edit')return teacherEditor(id);
if(action==='teacher-reset')return teacherReset(id);
if(action==='teacher-status'){const t=find('teachers',id);await api('teachers/status',{id,active:!t.active});await load();return toast('Đã cập nhật trạng thái tài khoản')}
if(action==='class-comment')return classComment();
if(action==='resource-type')return resourceEditor(undefined,id,'games');
if(action==='ai-editor')return aiEditor();
if(action==='ai-settings')return aiSettings();
if(action==='json-import')return jsonImport();
if(action==='school')return modalForm('🏫 Thông tin nhà trường',field('name','Tên trường',state.school)+field('address','Địa chỉ',state.school_info.address||'','text','',false)+field('phone','Điện thoại',state.school_info.phone||'','text','',false)+field('principal','Hiệu trưởng',state.school_info.principal||'','text','',false),d=>api('school',d));
return await handleActionOld(button);
}catch(e){toast(e.message,true)}};

